static freelist_idx_t next_random_slot(union freelist_init_state *state)
{
	freelist_idx_t result;

	if (state->count == 0)
		return 0;
	result = (state->list[state->pos] + state->rand) % state->count;
	state->pos++;
	if (state->pos >= state->count)
		state->pos = 0;
	return result;
}

